<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { LoaderCircle, Pencil, Plus, Trash2, X } from "lucide-vue-next";
import { useRoute } from "vue-router";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import StatusBadge from "@/components/operations/StatusBadge.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import { platformRepository } from "@/data/repositories/platformRepository";
import type { UiMemberRecord, UiStudentRecord, UiTeachingClass } from "@/data/models/operations";
import type { UiCatalog } from "@/data/models/platform";

const route = useRoute(); const instituteId = () => Number(route.params.instituteId); const loading = ref(true); const saving = ref(false); const error = ref(""); const classes = ref<UiTeachingClass[]>([]); const members = ref<UiMemberRecord[]>([]); const students = ref<UiStudentRecord[]>([]); const catalog = ref<UiCatalog | null>(null); const editing = ref<UiTeachingClass | null>(null); const formOpen = ref(false); const deleteTarget = ref<UiTeachingClass | null>(null);
const defaults = { name: "", course_id: null as number | null, subject_id: null as number | null, teacher_user_id: null as number | null, status: "active", student_user_ids: [] as number[] }; const form = reactive({ ...defaults });
async function load() { loading.value = true; error.value = ""; try { const [classData, memberPage, studentPage, catalogData] = await Promise.all([operationsRepository.teachingClasses(instituteId()), operationsRepository.members(instituteId(), { per_page: 100 }), operationsRepository.students({ institute_id: instituteId(), per_page: 100 }), platformRepository.catalog()]); classes.value = classData; members.value = memberPage.items; students.value = studentPage.items; catalog.value = catalogData; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load classes."; } finally { loading.value = false; } }
function openCreate() { editing.value = null; Object.assign(form, { ...defaults, student_user_ids: [] }); formOpen.value = true; }
function openEdit(item: UiTeachingClass) { editing.value = item; Object.assign(form, { name: item.name, course_id: item.courseId, subject_id: item.subjectId, teacher_user_id: item.teacherUserId, status: item.status, student_user_ids: [...item.studentUserIds] }); formOpen.value = true; }
async function save() { saving.value = true; error.value = ""; try { if (editing.value) await operationsRepository.updateTeachingClass(instituteId(), editing.value.id, form); else await operationsRepository.createTeachingClass(instituteId(), form); formOpen.value = false; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save class."; } finally { saving.value = false; } }
async function remove() { if (!deleteTarget.value) return; saving.value = true; try { await operationsRepository.removeTeachingClass(instituteId(), deleteTarget.value.id); deleteTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to remove class."; } finally { saving.value = false; } }
onMounted(load);
</script>
<template><div class="space-y-5"><div class="flex items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-violet">Teaching structure</p><h2 class="mt-1 text-[26px] font-bold">Classes</h2><p class="mt-1 text-[13px] text-ink3">Group institute students and assign an active teacher.</p></div><button class="ops-button-primary flex items-center gap-2" @click="openCreate"><Plus :size="15" /> Add class</button></div><p v-if="error" class="rounded-xl bg-pink-light p-3 text-[12px] text-pink">{{ error }}</p><DataPanel title="Institute classes" :description="`${classes.length} classes`" :loading="loading" :empty="!classes.length"><div class="grid gap-3 p-4 md:grid-cols-2"><article v-for="item in classes" :key="item.id" class="rounded-xl border border-border p-4"><div class="flex items-start justify-between"><div><h3 class="font-bold">{{ item.name }}</h3><p class="mt-1 text-[11px] text-ink3">{{ item.subjectName || 'All subjects' }} · {{ item.courseName || 'All courses' }}</p></div><StatusBadge :value="item.status" /></div><p class="mt-3 text-[12px]">Teacher: <strong>{{ item.teacherName || 'Unassigned' }}</strong></p><p class="mt-1 text-[11px] text-ink3">{{ item.studentUserIds.length }} student(s)</p><div class="mt-3 flex justify-end gap-1"><button class="ops-icon-button" title="Edit class" @click="openEdit(item)"><Pencil :size="14" /></button><button class="ops-icon-button text-pink" title="Delete class" @click="deleteTarget = item"><Trash2 :size="14" /></button></div></article></div></DataPanel><OpsModal :open="formOpen" max-width="max-w-2xl" :close-on-backdrop="!saving" @close="formOpen = false"><form class="max-h-[90vh] overflow-y-auto rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="save"><div class="flex justify-between"><div><h3 class="text-[17px] font-bold">{{ editing ? 'Edit class' : 'Create class' }}</h3><p class="mt-1 text-[12px] text-ink3">Only active institute students and teachers can be assigned.</p></div><button type="button" @click="formOpen = false"><X :size="18" /></button></div><div class="mt-5 grid gap-3 sm:grid-cols-2"><label class="text-[11px] font-semibold sm:col-span-2">Class name<input v-model="form.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Course<select v-model="form.course_id" class="ops-input"><option :value="null">All courses</option><option v-for="item in catalog?.courses || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Subject<select v-model="form.subject_id" class="ops-input"><option :value="null">All subjects</option><option v-for="item in catalog?.subjects || []" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Teacher<select v-model="form.teacher_user_id" class="ops-input"><option :value="null">Unassigned</option><option v-for="item in members.filter((member) => member.roleSlug === 'teacher')" :key="item.userId" :value="item.userId">{{ item.name }}</option></select></label><label class="text-[11px] font-semibold">Status<select v-model="form.status" class="ops-input"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><fieldset class="sm:col-span-2"><legend class="mb-2 text-[11px] font-semibold">Students</legend><div class="grid max-h-48 gap-2 overflow-y-auto rounded-xl border border-border p-3 sm:grid-cols-2"><label v-for="student in students" :key="student.userId" class="flex items-center gap-2 text-[11px]"><input v-model="form.student_user_ids" type="checkbox" :value="student.userId" />{{ student.name }}</label></div></fieldset></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="ops-button-secondary" @click="formOpen = false">Cancel</button><button :disabled="saving" class="ops-button-primary inline-flex items-center gap-2"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : 'Save class' }}</button></div></form></OpsModal><ConfirmModal :open="Boolean(deleteTarget)" title="Delete class?" :message="`Delete ${deleteTarget?.name || 'this class'}? Student accounts are not deleted.`" confirm-label="Delete class" :busy="saving" tone="danger" @close="deleteTarget = null" @confirm="remove" /></div></template>
